    "id": "w14/3.6/p19",
    "sentences": [
      {
        "id": "w14/3.6/p19/s1",
        "parts": [
          {
            "text": "Duodenoan gertatzen den moduan, nahiz eta arearen hastapen hau peritoneo barruko egitura bat izan atzeko mesoduodenoan garatzen delako, duodenoaren biraketarekin batera mesoduodeno hori desagertzen da eta "
          },
          {
            "text": "area ere peritoneoaren atzekaldean kokatzen da",
            "b": true
          },
          {
            "text": " ia guztiz. "
          }
        ]
      },
      {
        "id": "w14/3.6/p19/s2",
        "parts": [
          {
            "text": "Batzuetan buztana lotailu esplenorrenalaren bi orrien artean sartzen da."
          }
        ]
      }
    ]
